void SortBoard(List<Player> players) {
    // by name first, then by score: equal scores will keep the name order
    players.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));
    players.Sort((a, b) => b.Score.CompareTo(a.Score));
}

