static ulong TransparentKey(ushort layer, short order, float depth) {   // depth ≥ 0
    uint d = (uint)BitConverter.SingleToInt32Bits(depth);  // .NET Standard 2.1; in Burst, math.asuint
    return ((ulong)layer << 48)
         | ((ulong)(ushort)(order + 32768) << 32)          // −32768..32767 → 0..65535
         | (ulong)~d;                                      // far ones first: back to front
}

for (int i = 0; i < count; i++) keys[i] = TransparentKey(layer[i], order[i], depth[i]);
Array.Sort(keys, ids, 0, count);    // one ulong comparison instead of three fields

