// one radix pass: stably distributes src into dst by the byte at shift
static void RadixPass(ulong[] src, ulong[] dst, int n, int shift) {
    Span<int> count = stackalloc int[257];
    for (int i = 0; i < n; i++) count[(int)((src[i] >> shift) & 0xFF) + 1]++;
    for (int b = 0; b < 256; b++) count[b + 1] += count[b];   // count[b] is the first slot of byte b
    for (int i = 0; i < n; i++)                               // left to right: stable
        dst[count[(int)((src[i] >> shift) & 0xFF)]++] = src[i];
}
// the whole sort: shift = 0, 8, …, 56, swapping src and dst each time

