public void SortColors(int[] a) {
    int lo = 0, mid = 0, hi = a.Length - 1;
    while (mid <= hi) {
        if (a[mid] == 0) { (a[lo], a[mid]) = (a[mid], a[lo]); lo++; mid++; }
        else if (a[mid] == 1) mid++;
        else { (a[mid], a[hi]) = (a[hi], a[mid]); hi--; }   // mid stays: the new a[mid] is unchecked
    }
}
// [2, 0, 2, 1, 1, 0]: 2 ↔ a[5] → [0, 0, 2, 1, 1, 2], hi = 4
// 0 in place → lo = mid = 1; 0 in place → lo = mid = 2
// 2 ↔ a[4] → [0, 0, 1, 1, 2, 2], hi = 3; 1, 1 → mid = 4 > hi — done
